mapper.select:
SELECT course_id, course_name
FROM m_course
WHERE hidden_flg
= #{hiddenFlg}
AND delete_flg = #{deleteFlg}
ORDER BY course_id ASC;

SELECT place_id, place_name
FROM m_place 
WHERE place_id = #{placeId}
AND delete_flg = #{deleteFlg}

SELECT company_id, company_name 
FROM m_company 
WHERE delete_flg = #{deleteFlg} 
ORDER BY company_id ASC;

SELECT
l.lms_user_id,
u.user_id,
u.user_name,
c.course_id,
c.course_name,
comp.company_name,
p.place_name 
From m_lms_user l
INNER JOIN m_user u
ON l.user_id = u.user_id AND u.delete_flg = #{deleteFlg}
LEFT OUTER JOIN
t_user_company us
ON l.lms_user_id = us.lms_user_id AND us.delete_flg =
#{deleteFlg}
LEFT OUTER JOIN m_company comp
ON us.company_id =
comp.company_id AND comp.delete_flg = #{deleteFlg}
LEFT OUTER JOIN
t_course_user cu
ON l.lms_user_id = cu.lms_user_id AND cu.delete_flg =
#{deleteFlg}
LEFT OUTER JOIN m_course c
ON cu.course_id = c.course_id
AND c.delete_flg = #{deleteFlg}
LEFT OUTER JOIN t_user_place up
ON
l.lms_user_id = up.lms_user_id AND up.delete_flg = #{deleteFlg}
LEFT
OUTER JOIN m_place p
ON up.place_id = p.place_id AND p.delete_flg =
#{deleteFlg}
WHERE
l.delete_flg = #{deleteFlg}

	AND c.course_id = #{courseId}


	AND comp.company_id = #{companyId}


	AND u.user_name LIKE '%' || #{userName} || '%'


	AND p.place_id = #{placeId}


	AND l.role = #{role}
